-- Dansk portion 2 del 3/3: 166 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 6581-9977.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish2'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish2', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":6581,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Staten giver subsidier til landbruget.' Hvad er det, staten giver?","o":["gode råd","nye regler","økonomisk støtte","særlige bøder"],"a":"økonomisk støtte","r":"Subsidier er tilskud fra det offentlige. De skal gøre det lettere at drive en bestemt type produktion eller virksomhed."},
{"l":6603,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En dømt person vil 'anke' dommen. Hvad vil vedkommende?","o":["betale bøden i mindre rater over flere år","slette sagen fra alle offentlige papirer","afsone straffen med det samme","have sagen prøvet ved en højere domstol"],"a":"have sagen prøvet ved en højere domstol","r":"At anke er at klage over en dom, så en højere domstol ser på sagen igen. Det gælder både den tiltalte og anklageren."},
{"l":6626,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Opgaven fordrer stor tålmodighed.' Hvilket ord kan erstatte 'fordrer'?","o":["kræver","fjerner","mangler","skjuler"],"a":"kræver","r":"'Fordre' er et formelt ord for at kræve. Det beslægtede navneord er 'fordring', som er et krav."},
{"l":6643,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord er stavet rigtigt? Det er sort slik med en kraftig smag.","o":["lakrits","lakrids","lakris","lagrids"],"a":"lakrids","r":"Ordet ender på -ds, selvom d'et ikke høres, ligesom i 'kreds'."},
{"l":6668,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er forskellen på forfatteren og fortælleren?","o":["Forfatteren er stemmen i teksten, fortælleren har skrevet den","Forfatteren er altid opdigtet, fortælleren er en rigtig person","Forfatteren har skrevet teksten, fortælleren er stemmen i den","Der er ingen forskel, for de to ord betyder præcis det samme"],"a":"Forfatteren har skrevet teksten, fortælleren er stemmen i den","r":"Forfatteren er et virkeligt menneske, mens fortælleren er den stemme, forfatteren har skabt. Derfor må man ikke sætte lighedstegn mellem dem."},
{"l":6686,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Bestyrelsen vedtog forslaget enstemmigt.' Hvad betyder det?","o":["kun formanden stemte for","et lille flertal stemte for","ingen stemte overhovedet","alle stemte for"],"a":"alle stemte for","r":"Enstemmigt betyder med én stemme, altså at alle stemte det samme. Der var ingen, der stemte imod."},
{"l":6702,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"En novelle begynder med, at Ali står på stranden og ikke tør gå ud i vandet. Den slutter med, at Ali står samme sted igen, men nu løber lige ud i bølgerne. Hvilken komposition er det?","o":["cirkelkomposition","brevform","parallelhandling","in medias res"],"a":"cirkelkomposition","r":"Teksten slutter, hvor den begyndte, og det viser, hvor meget Ali har ændret sig. Det kaldes cirkelkomposition."},
{"l":6723,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En 'kronisk' sygdom varer ved. Hvad kaldes en sygdom, der kommer pludseligt og varer kort?","o":["arvelig","akut","alvorlig","smitsom"],"a":"akut","r":"Akut bruges om noget, der opstår pludseligt og kræver handling nu. Ordet bruges også i 'akutmodtagelse'."},
{"l":6747,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Skolen vil gerne have et godt ___ i klasserne.'","o":["milljø","milyø","miljø","miljøe"],"a":"miljø","r":"Ordet stammer fra fransk 'milieu'. På dansk skrives det med lj og ø."},
{"l":6768,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'desinformation'?","o":["gamle oplysninger, man har glemt at rette","sande oplysninger, der er hemmelige","reklamer, der er tydeligt mærket","falske oplysninger, der spredes med vilje"],"a":"falske oplysninger, der spredes med vilje","r":"Forskellen til en almindelig fejl er hensigten. Bag desinformation står nogen, der ønsker at vildlede modtagerne."},
{"l":6786,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find ordet: 'Vi byggede en ny ___ bag huset, så vi kan spise udenfor.'","o":["terrasse","terasse","terrase","tærrasse"],"a":"terrasse","r":"Ordet har både dobbelt-r og dobbelt-s."},
{"l":6800,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Mange produkter reklamerer med ordet naturlig, som om det betød sundt. Men slangegift og brændenælder er også naturlige.' Hvad vil teksten vise?","o":["Naturlige produkter er farligere end andre varer","Naturligt betyder ikke altid, at noget er sundt","Brændenælder er sundere, end de fleste tror","Reklamer bør ikke handle om sundhed og slanger"],"a":"Naturligt betyder ikke altid, at noget er sundt","r":"Slangegift og brændenælder er naturlige, men de er ikke sunde. Så ordet 'naturlig' betyder ikke automatisk, at noget er sundt."},
{"l":6820,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket spørgsmål slutter rigtigt med en forkortelse?","o":["Har du set løver, tigre osv?.","Har du set løver, tigre osv?","Har du set løver, tigre osv.?","Har du set løver, tigre. osv?"],"a":"Har du set løver, tigre osv.?","r":"Forkortelsen beholder sit punktum, og spørgsmålstegnet følger bagefter."},
{"l":6840,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form skal stå i opskriften: '___ dejen på bordet, og lad den hvile i en time.'?","o":["Lig","Lægge","Ligge","Læg"],"a":"Læg","r":"Du gør noget ved dejen, så verbet er 'lægge', og bydeformen er 'læg'. 'Lig' er bydeform af 'ligge', og det kan ikke have et genstandsled."},
{"l":6861,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Forbrugere laver en 'boykot' af et firma. Hvad gør de?","o":["nægter at købe firmaets varer i protest","samler underskrifter imod firmaet","demonstrerer foran firmaets hovedkontor","går i strejke på firmaets fabrikker"],"a":"nægter at købe firmaets varer i protest","r":"At boykotte er at holde sig væk, så man køber ikke varerne. Ordet stammer fra godsforvalteren Charles Boycott i Irland, som lokalbefolkningen i 1880 nægtede at have noget med at gøre."},
{"l":6882,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er hele verballeddet i: 'Hassan har aldrig været i Paris.'?","o":["har aldrig været","har været","været i Paris","aldrig været"],"a":"har været","r":"Verballeddet består her af to verber, 'har' og 'været'. 'Aldrig' står imellem dem, men det er et biord og hører ikke med."},
{"l":6900,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skolen er blevet en fabrik, hvor eleverne kører ned ad samlebåndet og bliver sorteret efter karakter, før de sendes videre til næste station.' Hvad kritiserer skribenten med billedet?","o":["At skolen bruger for mange penge på teknisk udstyr","At eleverne får for lidt praktisk arbejde i timerne","At eleverne behandles som varer og ikke som mennesker","At skolen ligger for tæt på byens gamle fabrikker"],"a":"At eleverne behandles som varer og ikke som mennesker","r":"Fabrik, samlebånd og sortering hører til varer. Billedet siger, at skolen behandler børn, som om de var varer, og ikke ser den enkelte."},
{"l":6920,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord kræves der komma: 'Den cykel Noah fik i fødselsdagsgave er allerede punkteret.'?","o":["Noah","er","allerede","fødselsdagsgave"],"a":"fødselsdagsgave","r":"Ledsætningen 'Noah fik i fødselsdagsgave' mangler ordet 'som', men slutter stadig med komma."},
{"l":6942,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'I grupperne skal I ___ tekstens budskab.'","o":["diskutere","diskuttere","diskuterer","disskutere"],"a":"diskutere","r":"Efter 'skal' står navneform, altså uden r til sidst. Ordet har kun ét s og ét t."},
{"l":6960,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Det handler om en stat i USA. Hvilken form er rigtig: '___ hovedstad er Austin.'?","o":["Texas's","Texas'","Texass","Texa's"],"a":"Texas'","r":"Stednavne på s får kun apostrof i genitiv."},
{"l":6981,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I en vejledning står der: 'Kopier forefindes på kontoret.' Hvad betyder det?","o":["der mangler kopier på kontoret","der skal laves kopier på kontoret","der ligger kopier på kontoret","der må ikke tages kopier på kontoret"],"a":"der ligger kopier på kontoret","r":"'Forefindes' er et stift, formelt ord for at findes eller være til stede. I hverdagssprog vil man sige 'der ligger'."},
{"l":7000,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Nu skal du høre, sagde min mor, og hendes stemme fik det lille knæk, den altid fik, inden hun gjorde tingene pænere, end de var.' Hvad kan fortælleren forvente?","o":["At mor vil komme med en glad nyhed","At mor er ved at blive forkølet","At mor vil synge noget for fortælleren","At mor vil pynte på sandheden"],"a":"At mor vil pynte på sandheden","r":"Knækket er et kendt tegn: Fortælleren ved af erfaring, at nu kommer en pæn omskrivning. Det ligger i ordet 'altid'."},
{"l":7020,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige tillægsform: 'Hun har ___ armen i vejret for at svare.'","o":["strakt","stragt","strækt","straket"],"a":"strakt","r":"Tillægsformen af 'strække' skifter æ til a og skrives med kt."},
{"l":7040,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning har et overflødigt komma?","o":["Bogen handlede om vikinger, og den var spændende.","Bogen om vikingerne, var meget spændende.","Bogen var spændende, men den var lang.","Da bogen var slut, var jeg ked af det."],"a":"Bogen om vikingerne, var meget spændende.","r":"'Bogen om vikingerne' er grundleddet og ikke en ledsætning, så der må ikke være komma foran 'var'."},
{"l":7060,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Vi spiser and til Mortensaften hos Oliver i Vejle.'?","o":["Oliver","Vejle","Mortensaften","Vi"],"a":"Mortensaften","r":"Mærkedage som mortensaften og juleaften skrives med lille."},
{"l":7080,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Før i tiden rettede hver by sig efter solen, og klokken var derfor ikke helt den samme i København og Esbjerg. Da jernbanen bredte sig, blev det et problem.' Hvorfor blev det sandsynligvis et problem?","o":["Tog kunne ikke køre, når solen var nede","Der kom flere ure i de små danske byer","Folk i Esbjerg stod senere op end i København","Køreplaner kræver, at alle bruger samme tid"],"a":"Køreplaner kræver, at alle bruger samme tid","r":"Teksten siger det ikke direkte, men et tog mellem to byer med forskellig klokkeslæt gør afgangstider uklare. Det er slutningen, læseren skal lave."},
{"l":7102,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Lærerne har klaget over lugten fra skolens kantine. Kantinelederen svarer, at ingen elever nogensinde har sagt noget om den.' Hvad er svagheden i kantinelederens svar?","o":["Det viser ikke, at lærerne tager fejl","Det viser, at eleverne er ligeglade med lugten","Det siger ikke, hvad kantinen laver af mad","Det giver lærerne fuldt ud ret i deres klage"],"a":"Det viser ikke, at lærerne tager fejl","r":"Kantinelederen taler om elevernes tavshed i stedet for om lugten. At eleverne ikke har klaget, viser ikke, at der ikke lugter."},
{"l":7124,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvordan skrives udtrykket? 'Vi var på museum ___, altså for to dage siden.'","o":["iforgårs","i forgårs","i forgår","i forgås"],"a":"i forgårs","r":"Udtrykket skrives i to ord og ender på -gårs med s."},
{"l":7150,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Ledsætningen står først og er sætningens grundled. Efter hvilket ord skal der komma: 'At du kom til tiden gjorde mig glad.'?","o":["du","gjorde","tiden","mig"],"a":"tiden","r":"'At du kom til tiden' er en ledsætning, selvom den er grundled, og den slutter efter 'tiden'."},
{"l":7169,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg det rigtige ord: 'Holdet havde et stærkt ___, og alle hjalp hinanden.'","o":["fælleskab","fællesskap","fælledskab","fællesskab"],"a":"fællesskab","r":"Ordet består af 'fælles' og endelsen '-skab', så der skal to s'er med."},
{"l":7192,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Alle elever med feber bliver sendt hjem fra skolen. Liam er blevet sendt hjem. Altså har Liam feber.' Hvad er fejlen i slutningen?","o":["Man kan blive sendt hjem af andre grunde end feber","Feber kan kun måles af skolens sygeplejerske","Feber er ikke en god nok grund til at sende elever hjem","Skolen sender aldrig elever hjem, før forældrene er spurgt"],"a":"Man kan blive sendt hjem af andre grunde end feber","r":"Reglen siger, at feber fører til hjemsendelse, ikke at hjemsendelse kun skyldes feber. Slutningen vender logikken om."},
{"l":7212,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at en lærer er 'konsekvent'?","o":["hun giver altid eleverne høje karakterer","hun handler efter de samme regler hver gang","hun bliver hurtigt vred på sin klasse","hun ændrer planen efter dagens humør"],"a":"hun handler efter de samme regler hver gang","r":"Den, der er konsekvent, gør det, han eller hun har sagt, hver gang. Mange tror, det betyder 'hård', men det betyder 'stabil og forudsigelig'."},
{"l":7230,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket værk er skrevet af Tove Ditlevsen?","o":["Den afrikanske Farm","Haabløse Slægter","Barndommens gade","Lykke-Per"],"a":"Barndommens gade","r":"'Barndommens gade' fra 1943 er en af Tove Ditlevsens kendte romaner og foregår på Vesterbro."},
{"l":7250,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Eleverne skal stille begivenhederne op 'kronologisk'. Hvordan gør de det?","o":["efter hvor vigtige de var","efter alfabetet","efter hvor de fandt sted","efter hvornår de skete"],"a":"efter hvornår de skete","r":"Kronologisk betyder i tidsmæssig rækkefølge. Ordet kommer af det græske ord 'chronos', som betyder tid."},
{"l":7272,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Aftalen 'hænger i en tynd tråd'. Hvad betyder det?","o":["den er tæt på at gå i stykker","den er meget lang og indviklet","den er kun lige blevet skrevet","den bliver holdt hemmelig"],"a":"den er tæt på at gå i stykker","r":"En tynd tråd kan knække når som helst. Udtrykket bruges om noget, der er i stor fare for at mislykkes."},
{"l":7295,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Drengen var ___, da hans hund blev væk.'","o":["fortvivled","fortvivlet","fortvivlt","fordvivlet"],"a":"fortvivlet","r":"Ordet indeholder 'tvivl' og ender på -et."},
{"l":7311,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket udtryk er et påpegende (demonstrativt) stedord i: 'Hvem ejer den her jakke, som lå på gulvet?'","o":["Hvem","som","den her","gulvet"],"a":"den her","r":"'Den her' peger på en bestemt jakke. 'Hvem' er et spørgende stedord, og 'gulvet' er et navneord."},
{"l":7332,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad viser man, når man 'tager initiativet'?","o":["at man adlyder andres ordrer","at man sætter sig ind i reglerne","at man undskylder en fejl","at man selv sætter noget i gang"],"a":"at man selv sætter noget i gang","r":"Den, der tager initiativet, venter ikke på andre, men tager det første skridt."},
{"l":7351,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Hun har en ___ måde at grine på.'","o":["speciel","spesiel","speciell","specjel"],"a":"speciel","r":"Lyden s skrives med c, og ordet ender med ét l. Først i flertal 'specielle' bliver der dobbelt-l."},
{"l":7374,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Håndboldklubbens generalforsamling vedtog i går med 14 stemmer mod 11 at samle to hold. Formanden for ungdomsudvalget kalder det en stor dag for klubben. Forældregruppen kalder det en sort dag.' Hvad kan man ikke afgøre ud fra teksten?","o":["Hvor mange der stemte for og imod forslaget i går","Om det bliver godt for spillerne at samle holdene","Hvad medlemmerne besluttede på mødet i går","Hvad forældregruppen synes om det"],"a":"Om det bliver godt for spillerne at samle holdene","r":"Teksten fortæller, hvad der blev vedtaget, og hvad to parter synes. Men om det bliver godt, ved ingen endnu. Det må tiden vise."},
{"l":7393,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Skibet tog sten om bord som ___, så det lå roligt i vandet.'","o":["balast","ballasst","ballast","ballest"],"a":"ballast","r":"Ordet har dobbelt-l og ét s og ender på -ast. Det er ekstra vægt, der holder skibet stabilt."},
{"l":7408,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Et træ i skoven står sjældent helt alene. Dets rødder er forbundet med tynde svampetråde, som kan flytte næring mellem træerne. Forskere diskuterer stadig, hvor stor betydning det har.' Hvad er sikkert, og hvad er usikkert ifølge teksten?","o":["Trådene er en gammel myte, som forskerne ikke tror på","De betyder meget, men ingen har set dem endnu","Forskerne er enige om, at træerne ikke kan undvære dem","Trådene findes, men ingen ved, hvor meget de betyder"],"a":"Trådene findes, men ingen ved, hvor meget de betyder","r":"Der står, at trådene kan flytte næring. Men 'diskuterer stadig' viser, at forskerne ikke er enige om, hvor meget det betyder."},
{"l":7431,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Elevtallet i Nørreby faldt fra 900 i 2010 til 600 i 2019. I 2020 var det også 600. Kommunens folder har kun de to sidste år med og skriver: Elevtallet er stabilt.' Hvad har kommunen gjort?","o":["Kun vist de to år, så man ikke ser det store fald","Regnet forkert i tallene for 2019 og 2020","Vist, at elevtallet steg i årene efter 2010","Vist alle de år, hvor tallet har ændret sig"],"a":"Kun vist de to år, så man ikke ser det store fald","r":"Det passer, at tallet var 600 begge år. Men folderen viser ikke, at der før var 900 elever, og så ser det pænere ud, end det er."},
{"l":7449,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Alle på holdet kom til træning, med ___ af Emma.'","o":["untagelse","undtagelse","undtaggelse","unntagelse"],"a":"undtagelse","r":"Ordet kommer af 'undtage'. D'et skal med, selvom det ikke høres, og der er ét g."},
{"l":7468,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'dystopi'?","o":["en fortælling om et lykkeligt fremtidssamfund","en fortælling om konger fra middelalderen","en fortælling om et skræmmende fremtidssamfund","en fortælling om to unge, der forelsker sig"],"a":"en fortælling om et skræmmende fremtidssamfund","r":"En dystopi viser et samfund, hvor alt er gået galt. Det modsatte er en utopi, som beskriver et drømmesamfund."},
{"l":7491,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find stavemåden: 'Kunstneren udstiller sine malerier i et ___.'","o":["galeri","gallerie","gallæri","galleri"],"a":"galleri","r":"Ordet har dobbelt-l, og det ender på -i uden e."},
{"l":7505,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Efter vaccinen er kroppen ___ over for sygdommen.'","o":["immun","imun","imunn","immuun"],"a":"immun","r":"Ordet har dobbelt-m i starten og ét n til sidst."},
{"l":7524,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma: 'Alt hvad hun sagde var sandt.'?","o":["hun","sagde","var","sandt"],"a":"sagde","r":"Ledsætningen 'hvad hun sagde' står inde i sætningen og afsluttes med komma."},
{"l":7545,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Anmeldelsen i skolebladet lød: Forestillingen er alt andet end en stor oplevelse. På teatrets plakat står der nu: En stor oplevelse! – Skolebladet.' Hvad har teatret gjort?","o":["Bedt skolebladet om at skrive en ny anmeldelse","Skrevet præcis det, anmelderen mente om stykket","Klippet i citatet, så det lyder som ros","Citeret skolebladet uden at nævne bladets navn"],"a":"Klippet i citatet, så det lyder som ros","r":"Anmelderen skrev 'alt andet end en stor oplevelse'. Teatret har fjernet de første ord, så en dårlig anmeldelse ligner ros."},
{"l":7566,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør en elev, der 'plæderer' for en ny skolegård?","o":["stemmer imod den og prøver at stoppe andre","tegner den op og giver den til rektoren","skriver om den og afleverer en opgave","taler for den og prøver at overbevise andre"],"a":"taler for den og prøver at overbevise andre","r":"At plædere er at føre en sag med argumenter, ligesom en forsvarer i retten gør. Ordet bruges meget i debatter og avisartikler."},
{"l":7589,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Der er en klar ___ mellem søvn og humør.'","o":["sammenhæng","sammenheng","samenhæng","sammenhænd"],"a":"sammenhæng","r":"Ordet hænger sammen med udtrykket 'hænge sammen', så der er dobbelt-m og æ."},
{"l":7611,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvordan er et 'rigidt' regelsæt?","o":["smidigt og let at tilpasse","stift og uden plads til undtagelser","kort og let at huske","nyt og endnu ikke afprøvet"],"a":"stift og uden plads til undtagelser","r":"Rigid kommer af latin og betyder stiv. Et rigidt system bøjer ikke af, heller ikke når reglerne passer dårligt."},
{"l":7630,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning er passiv af: 'Man åbner butikken klokken ni.'?","o":["Butikken åbner klokken ni.","Butikken åbnede klokken ni.","Butikken åbnes klokken ni.","Man åbnes butikken klokken ni."],"a":"Butikken åbnes klokken ni.","r":"Passiv kræver her s-form: 'åbnes'. 'Butikken åbner' ligner, men verbet står i aktiv og har ikke -s."},
{"l":7652,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Killingen ___ godt hos os sidste år.'?","o":["trives","trivede","trivet","trivedes"],"a":"trivedes","r":"'Sidste år' kræver datid. 'Trives' beholder sit -s i datid og bliver til 'trivedes'."},
{"l":7671,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'varm' og 'kold' i forhold til hinanden?","o":["antonymer","synonymer","homonymer","akronymer"],"a":"antonymer","r":"'Anti' betyder imod, og 'onym' betyder navn. Antonymer er ord med modsat betydning, mens synonymer har samme betydning."},
{"l":7693,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Flagermus er ikke blinde. De fleste arter ser fint, men mange bruger også ekko til at finde insekter i mørke.' Hvilken slutning går længere, end teksten giver lov til?","o":["Det er en myte, at flagermus er blinde","Flagermus kan ikke fange insekter uden ekko","Mange flagermus kan orientere sig med lyd","Mange flagermus har mere end én sans at bruge"],"a":"Flagermus kan ikke fange insekter uden ekko","r":"Teksten siger, at mange bruger ekko, ikke at det er nødvendigt. Det er forskellen på 'bruger' og 'kan ikke undvære'."},
{"l":7712,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken dansk forfatter modtog Nobelprisen i litteratur i 1944?","o":["Karen Blixen","Tom Kristensen","Johannes V. Jensen","Martin A. Hansen"],"a":"Johannes V. Jensen","r":"Johannes V. Jensen fik prisen i 1944. Han er blandt andet kendt for 'Kongens Fald' og 'Himmerlandshistorier'."},
{"l":7729,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Pandaer lever ___ af bambus.'","o":["hovesagelig","hovedsalig","hovedsagli","hovedsagelig"],"a":"hovedsagelig","r":"Ordet hænger sammen med 'hovedsag' og ender på -elig. Både d'et og g'et skal med."},
{"l":7751,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå i skriftsprog: 'Er der ___ vindue åbent på skolen?'?","o":["noget","nogen","nogle","alle"],"a":"noget","r":"'Vindue' er et intetkønsord i ental, så stedordet skal stå i intetkøn: 'noget'."},
{"l":7773,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ordklasse tilhører det sammensatte ord 'vandtæt'?","o":["navneord","tillægsord","udsagnsord","biord"],"a":"tillægsord","r":"I et sammensat ord bestemmer efterleddet ordklassen. 'Tæt' er et tillægsord, selv om forleddet 'vand' er et navneord."},
{"l":7792,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Ren' kan både betyde 'ikke beskidt' og være navnet på et dyr med gevir. Hvad kaldes ord af den slags?","o":["antonymer","synonymer","homonymer","akronymer"],"a":"homonymer","r":"Homonymer staves og udtales ens, men har forskellig betydning og oprindelse. 'Homo' betyder ens, og 'onym' betyder navn."},
{"l":7807,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Søjlerne viser, hvor mange minutter elever læser om dagen: 5. klasse 30, 7. klasse 20 og 9. klasse 15. Under grafen står: Undersøgelsen måler kun læsning af bøger på papir.' Hvad kan man på grund af den oplysning ikke sige ud fra grafen?","o":["Om de ældste læser mindre i papirbøger end de yngste","Om 5. klasse læser mere på papir end 9. klasse","Hvor mange minutter 7. klasse læser i bøger","Hvor meget eleverne læser i alt"],"a":"Hvor meget eleverne læser i alt","r":"Læsning på skærm tæller ikke med. Måske læser de ældste mere på mobil og computer, så man kan ikke vide, hvor meget de læser i alt."},
{"l":7829,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvornår kaldes en måling 'valid'?","o":["når den faktisk måler det, den skal måle","når den er blevet trykt i et videnskabeligt blad","når den giver et tal med mange decimaler","når den er hurtig og billig at gennemføre"],"a":"når den faktisk måler det, den skal måle","r":"Validitet handler om gyldighed. Hvis en test af læsefærdighed i virkeligheden måler tempo, er den ikke valid."},
{"l":7850,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led er 'modne' i sætningen: 'Alle æblerne på træet er nu modne.'?","o":["genstandsled","omsagnsled","grundled","udsagnsled"],"a":"omsagnsled","r":"'Modne' står efter 'er' og fortæller, hvordan grundleddet 'alle æblerne på træet' er. Derfor er det et omsagnsled og ikke et genstandsled, og det står i flertal ligesom 'æblerne'."},
{"l":7872,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Vi bor i et ___ hus med store vinduer.'?","o":["modernt","modern","moderne","modernes"],"a":"moderne","r":"'Moderne' ender på -e og bøjes ikke. Det hedder altså både 'en moderne bil' og 'et moderne hus'."},
{"l":7894,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Klara synger ___ i koret.'?","o":["smuk","smukke","smukken","smukt"],"a":"smukt","r":"Ordet siger noget om verbet 'synger', altså hvordan hun synger. Så får tillægsordet -t og bruges som biord."},
{"l":7912,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad var 'hoveri' i dansk landbohistorie?","o":["pligtarbejde, som bønder skulle udføre på herregården","en fest, som blev holdt på gårdene efter hver høst","en skat, som købmænd i byerne skulle betale til kongen","en skole, som børnene på godset fik undervisning i"],"a":"pligtarbejde, som bønder skulle udføre på herregården","r":"Hoveri betød, at bønderne skulle arbejde gratis for godsejeren. Det var en vigtig del af fæstesystemet, og det forsvandt gradvist i løbet af 1800-tallet."},
{"l":7933,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da hun gik ud ad døren, vendte hun sig ikke om. Det havde hun lovet sig selv. Men hun gik langsomt.' Hvad antyder den sidste sætning?","o":["At hun er træt efter en lang dag på arbejde","At hun håber, at nogen vil kalde hende tilbage","At hun ikke kan finde sine sko i mørket","At hun er ligeglad med, hvad der er sket"],"a":"At hun håber, at nogen vil kalde hende tilbage","r":"Hun holder sit løfte, men kroppen tøver. 'Men' viser, at beslutningen er sværere, end hun vil vise."},
{"l":7953,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige form: 'Hendes tale var ___, og alle klappede længe.'","o":["fremrangende","fremragene","fremragende","fremmragende"],"a":"fremragende","r":"Ordet består af 'frem' og 'ragende'. Der er ét m, og -ende har d til sidst."},
{"l":7972,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvordan går det den, der 'kommer fra asken i ilden'?","o":["det går fra skidt til rigtig godt","det går hurtigere end forventet","det går, som det plejer at gå","det går fra dårligt til værre"],"a":"det går fra dårligt til værre","r":"Man forsøger at komme væk fra noget slemt, men havner i noget, der er endnu værre."},
{"l":7995,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord mangler? 'Hun drømmer om at blive ___ fodboldspiller.'","o":["professionel","proffessionel","professionell","profesionel"],"a":"professionel","r":"Ordet har ét f, dobbelt-s og ét l til sidst."},
{"l":8010,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er det at 'insinuere' noget?","o":["at sige noget ubehageligt højt foran hele klassen","at antyde noget ubehageligt uden at sige det direkte","at rose nogen for noget, de ikke har gjort selv","at bevise en påstand ved at finde nye fakta"],"a":"at antyde noget ubehageligt uden at sige det direkte","r":"Den, der insinuerer, siger noget skjult eller hentydende, så det er svært at svare igen. Det er normalt noget negativt om en anden."},
{"l":8032,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er forskellen på motiv og tema i en tekst?","o":["Motivet er forfatterens liv, temaet er tidens samfund","Motivet er bogens forside, temaet er dens overskrift","Motivet er det konkrete, temaet er det overordnede emne","Motivet er tekstens slutning, temaet er dens begyndelse"],"a":"Motivet er det konkrete, temaet er det overordnede emne","r":"Motivet er den konkrete situation, f.eks. en dreng der flytter. Temaet er det mere abstrakte emne, f.eks. at miste sit tilhørsforhold."},
{"l":8051,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad mangler? 'Jordskælvet var en ___ for hele regionen.'","o":["katastrophe","kattastrofe","katastroffe","katastrofe"],"a":"katastrofe","r":"Ordet kommer fra græsk, men på dansk skrives det med f, og kun ét f."},
{"l":8074,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Zainab læste om Vikingetiden på Nationalmuseet i København.'?","o":["Vikingetiden","Nationalmuseet","København","Zainab"],"a":"Vikingetiden","r":"Betegnelser for historiske perioder skrives med lille: vikingetiden, middelalderen."},
{"l":8093,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad spiser et dyr, som biologer kalder 'omnivor'?","o":["kun græs og blade","både planter og kød","kun andre dyr","kun insekter"],"a":"både planter og kød","r":"'Omni' betyder alt, og 'vor' kommer af latin for at æde. En omnivor er altså altædende, ligesom grise og mennesker."},
{"l":8115,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I rapporten er der en 'diskrepans' mellem to tal. Hvad betyder det?","o":["de er lige store","de er meget små","de stemmer ikke overens","de hører til samme år"],"a":"de stemmer ikke overens","r":"En diskrepans er en uoverensstemmelse. Ordet bruges især i faglige tekster om to ting, der burde passe sammen, men ikke gør det."},
{"l":8135,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Hun brugte en ___ til at klippe hjerterne ud.'","o":["skabellon","skabalon","skapelon","skabelon"],"a":"skabelon","r":"Ordet har ét l og b i midten og slutter på -on."},
{"l":8158,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord har den mest negative klang om en person, der sparer på sine penge?","o":["nærig","sparsommelig","økonomisk","fornuftig"],"a":"nærig","r":"Ordene kan beskrive den samme adfærd, men 'nærig' lyder som en kritik. De andre lyder neutrale eller positive."},
{"l":8180,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad kaldes et ords grundbetydning, sådan som den står i ordbogen?","o":["konnotation","denotation","anglicisme","sociolekt"],"a":"denotation","r":"Denotationen er det, ordet direkte betegner. Konnotationen er de følelser, det ellers vækker."},
{"l":8200,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad vil det sige, at en fortæller er neutral?","o":["Fortælleren kender alle personers tanker og hele fremtiden","Fortælleren er selv med i handlingen og siger jeg om sig selv","Fortælleren beskriver kun det ydre, som et kamera kan optage","Fortælleren tager åbent parti for hovedpersonen hele vejen"],"a":"Fortælleren beskriver kun det ydre, som et kamera kan optage","r":"En neutral fortæller holder sig udenfor og kommenterer ikke. Læseren må selv slutte sig til, hvad personerne føler."},
{"l":8219,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'En ___ i kredsløb om Jorden sender vejrbilleder ned til os.'","o":["sattelit","satelit","sattellit","satellit"],"a":"satellit","r":"Ordet har ét t først og dobbelt-l bagefter. Mange bytter om på dobbeltkonsonanterne."},
{"l":8242,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken stilretning forbindes særligt med Herman Bangs fortællekunst?","o":["impressionisme","surrealisme","konkretisme","barok"],"a":"impressionisme","r":"Herman Bang kaldes impressionist, fordi han gengiver indtryk, som de opleves, og lader læseren selv forstå sammenhængen."},
{"l":8261,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find stavemåden: 'Brugeren skal give sin ___, før appen må gemme data.'","o":["acept","accept","aksept","accebt"],"a":"accept","r":"Ordet har dobbelt-c og ender på -pt."},
{"l":8284,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kendetegner en impressionistisk fortælleteknik?","o":["Fortælleren forklarer grundigt personernes tanker","Fortælleren argumenterer åbent for en bestemt sag","Fortælleren træder tilbage og giver os sanseindtryk","Fortælleren bruger vers med fast rim og faste strofer"],"a":"Fortælleren træder tilbage og giver os sanseindtryk","r":"I impressionismen får læseren indtryk, replikker og små handlinger. Fortælleren forklarer så lidt som muligt."},
{"l":8304,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken fortælling af Karen Blixen blev til den Oscar-vindende film af Gabriel Axel?","o":["Sorg-Agre","Ehrengard","Den afrikanske Farm","Babettes Gæstebud"],"a":"Babettes Gæstebud","r":"Gabriel Axels film 'Babettes gæstebud' vandt en Oscar for bedste udenlandske film."},
{"l":8325,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Rejseguiden kalder landsbyen 'pittoresk'. Hvordan ser den ud?","o":["malerisk og charmerende","moderne og larmende","forladt og faldefærdig","fattig og beskidt"],"a":"malerisk og charmerende","r":"Pittoresk kommer af italiensk 'pittore', som betyder maler. Noget pittoresk er så smukt, at det kunne være et maleri."},
{"l":8346,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket tema går ofte igen i Tove Ditlevsens forfatterskab?","o":["Eventyrlige rejser på de store have","Hendes egen barndom og det at være kvinde","Oldtidens nordiske guder og deres helte","Livet på et stort adeligt gods i 1700-tallet"],"a":"Hendes egen barndom og det at være kvinde","r":"Tove Ditlevsen skrev om sin barndom på Vesterbro og om at være kvinde og forfatter."},
{"l":8373,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Lægen lyttede til patientens ___ med sit stetoskop.'","o":["åndedrett","ånderæt","åndedræt","åndedræd"],"a":"åndedræt","r":"Ordet består af 'ånde' og 'dræt'. Det slutter på -æt og har ét t."},
{"l":8393,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'dikotomi', for eksempel mellem natur og kultur?","o":["en sammensmeltning af flere dele","en samtale mellem to forskere","en lang række af små trin","en opdeling i to modsatte dele"],"a":"en opdeling i to modsatte dele","r":"'Di' betyder to, og 'tomi' betyder deling. Mange tekster bygger på en dikotomi, som for eksempel godt og ondt."},
{"l":8415,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hun trak 'nonchalant' på skuldrene. Hvordan gjorde hun det?","o":["ubekymret og ligeglad","vredt og bestemt","bange og rystende","glad og forventningsfuld"],"a":"ubekymret og ligeglad","r":"Nonchalant kommer fra fransk og betyder ubekymret. Ordet kan have en negativ klang, hvis man er for ligeglad med noget, der er vigtigt."},
{"l":8434,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det ville være nemt at sige, at det hele var Sebastians skyld. Det gjorde vi også.' Hvad ligger der i den sidste sætning?","o":["At det med sikkerhed var Sebastian, der havde hele skylden","At de gav Sebastian skylden, fordi det var nemmest","At de aldrig har talt med Sebastian om det, der skete","At Sebastian selv sagde, at det var hans skyld"],"a":"At de gav Sebastian skylden, fordi det var nemmest","r":"'Det ville være nemt' viser, at fortælleren ikke tror, at det hele var Sebastians skyld. 'Det gjorde vi også' indrømmer, at de sagde det alligevel."},
{"l":8457,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Mit ___ er at læse en bog om måneden.'","o":["nytårforsæt","nytårsforsæd","nytårsforsæt","nytårsforsat"],"a":"nytårsforsæt","r":"Ordet samles med fuge-s, og 'forsæt' betyder noget, man har sat sig for."},
{"l":8477,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket verbum står altid sammen med et tilbagevisende stedord?","o":["at vaske","at bade","at spise","at dumme"],"a":"at dumme","r":"Det hedder altid 'dumme sig': 'Jeg dummede mig.' 'Vaske' og 'bade' kan stå med 'sig', men de kan også stå uden: 'vaske bilen'."},
{"l":8499,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find ordet: 'Da Karl rejste fra Danmark til Amerika i 1880, var han set fra Danmark en ___.'","o":["emigrant","immigrant","emmigrant","imigrant"],"a":"emigrant","r":"En emigrant er en, der rejser ud af et land. Ordet skrives med e og ét m."},
{"l":8520,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad gør den, der 'fremturer' med sin påstand?","o":["trækker den forsigtigt tilbage","bliver stædigt ved med den","gør den lidt mere nuanceret","siger den for første gang"],"a":"bliver stædigt ved med den","r":"At fremture er at fastholde noget stædigt, også når andre har vist, at det er forkert. Ordet er negativt og lidt gammeldags."},
{"l":8542,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Den ærede forsamling bedes venligst indtage sine pladser, førend forestillingen tager sin begyndelse.' Hvilket stilleje er det?","o":["lavt stilleje","neutralt stilleje","højt stilleje","dialekt"],"a":"højt stilleje","r":"Højtidelige ord som 'førend' og 'ærede forsamling' giver et højt stilleje."},
{"l":8565,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning er tvetydig, fordi man ikke ved, hvem stedordet henviser til?","o":["Mia sagde til sin bror, at hun havde vundet.","Anton sagde til Mia, at han havde vundet.","Mia sagde til Anton, at hun havde vundet.","Mia sagde til sin søster, at hun havde vundet."],"a":"Mia sagde til sin søster, at hun havde vundet.","r":"'Hun' kan her være både Mia og søsteren. I de andre sætninger er kun én person af det rigtige køn."},
{"l":8590,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Det er et ___ spørgsmål, som ikke har betydning for sagens kerne.'","o":["perifert","periodisk","permanent","principielt"],"a":"perifert","r":"Perifer betyder 'ude i kanten'. Et perifert spørgsmål ligger uden for det, sagen egentlig handler om."},
{"l":8612,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Jeg står her ikke for at takke. Jeg står her, fordi jeg blev bedt om det.' Hvad viser taleren med de ord?","o":["At taleren er glad for at være blevet inviteret","At taleren ikke har lyst til at stå der","At taleren er beskeden og ikke vil fremhæves","At taleren er stolt af det, der skal fejres"],"a":"At taleren ikke har lyst til at stå der","r":"Taleren vil ikke takke og siger, at det kun er, fordi nogen bad om det. Det lyder, som om det er en pligt, og at taleren helst var fri."},
{"l":8640,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Hun er meget ___ og vil være den bedste i klassen.'","o":["ærgerig","ærgrig","ærgerrig","ærrgerrig"],"a":"ærgerrig","r":"Ordet slutter på -gerrig med dobbelt-r. Det betyder, at man vil nå langt, og må ikke forveksles med 'ærgerlig'."},
{"l":8659,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Ikke alle elever i 9.b har afleveret deres opgave.' Hvad følger med sikkerhed af sætningen?","o":["Ingen elever i 9.b har afleveret","Mindst én elev i 9.b har afleveret","De fleste elever i 9.b har afleveret","Mindst én elev i 9.b har ikke afleveret"],"a":"Mindst én elev i 9.b har ikke afleveret","r":"'Ikke alle' udelukker kun, at alle har afleveret. Teksten siger hverken, hvor mange der har, eller om nogen overhovedet har."},
{"l":8684,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvad fortæller 'hhv.' om alderen i: 'Ida og Noah er hhv. 14 og 15 år.'?","o":["Ida er 14 år, og Noah er 15 år","Ida og Noah er begge omkring 15 år","Ida er 15 år, og Noah er 14 år","Ida og Noah er mindst 14 år gamle"],"a":"Ida er 14 år, og Noah er 15 år","r":"'Hhv.' betyder 'henholdsvis' og fortæller, at tallene passer til navnene i samme rækkefølge."},
{"l":8702,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"I vurderingen af en skole er karakterer kun én 'parameter'. Hvad er det?","o":["en regel, som alle skoler skal følge","en af de ting, man bedømmer noget ud fra","et gennemsnit af alle målingerne","en grænse, man ikke må komme under"],"a":"en af de ting, man bedømmer noget ud fra","r":"Ordet er dannet af græsk for 'ved siden af' og 'mål'. Der er altså flere forhold at måle på end karaktererne."},
{"l":8719,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Instruktøren har store ambitioner. Det har en høne, der vil flyve over Atlanten, også.' Hvad mener anmelderen?","o":["Instruktøren burde lave en film om at flyve","Instruktøren tør mere end de fleste andre instruktører","Instruktøren vil mere, end evnerne rækker til","Filmen handler om dyr på en lang rejse"],"a":"Instruktøren vil mere, end evnerne rækker til","r":"Sammenligningen viser, at det ikke hjælper at ville noget stort, hvis man ikke kan. Den er ond, men klar."},
{"l":8743,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Hvis Sara har fået brevet, har hun ringet. Sara har ikke ringet.' Hvad følger logisk, hvis begge sætninger er sande?","o":["Sara er vred på afsenderen","Sara har fået brevet","Sara har mistet sin telefon","Sara har ikke fået brevet"],"a":"Sara har ikke fået brevet","r":"Hvis hun havde fået brevet, ville hun have ringet. Hun har ikke ringet, så hun har ikke fået det. Om hendes humør eller telefon siger teksten intet."},
{"l":8762,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilke tegn kan erstatte tankestregerne i: 'Min moster – hun er pilot – rejser meget.'?","o":["parenteser","koloner","semikoloner","bindestreger"],"a":"parenteser","r":"Både tankestreger og parenteser kan omslutte en indskudt bemærkning."},
{"l":8785,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kæmper en sproglig 'purist' for?","o":["at få flere fremmede ord ind i sproget","at holde sproget rent for fremmede ord","at afskaffe de svære stavemåder","at tale så højt og tydeligt som muligt"],"a":"at holde sproget rent for fremmede ord","r":"Latin 'purus' betyder ren. En purist vil gerne bevare sproget uden lån fra andre sprog."},
{"l":8805,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Det er ___ at tage prøven i dansk i 9. klasse.'","o":["obligatorist","oblikatorisk","obligatorisk","obbligatorisk"],"a":"obligatorisk","r":"Ordet ender på -isk og skrives med ét b og g."},
{"l":8827,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad er forskellen på analyse og fortolkning af en tekst?","o":["Analyse er at læse hurtigt, fortolkning at læse langsomt","Analyse handler om forfatteren, fortolkning om læseren","Analyse bruges om digte, fortolkning om romaner og noveller","Analyse viser tekstens træk, fortolkning siger, hvad de betyder"],"a":"Analyse viser tekstens træk, fortolkning siger, hvad de betyder","r":"Først undersøger man tekstens træk, f.eks. fortæller og billeder. Så samler man det hele i en tolkning af, hvad teksten vil sige."},
{"l":8850,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Kommunen har i år brugt 40 procent mere på vikarer end budgetteret. Det skyldes ifølge direktøren et højt sygefravær. Medarbejderne peger på, at sygefraværet skyldes, at der er for få ansatte.' Hvordan hænger de to forklaringer sammen?","o":["Medarbejderne forklarer, hvorfor der er så meget sygefravær","Medarbejderne siger, at der slet ikke er højt sygefravær","Direktøren giver medarbejderne ret i deres kritik","De er enige om, at der skal ansættes flere"],"a":"Medarbejderne forklarer, hvorfor der er så meget sygefravær","r":"Direktøren stopper ved sygefraværet. Medarbejderne går et skridt længere tilbage og siger, hvorfor der er sygefravær: Der er for få ansatte."},
{"l":8867,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kendetegner en 'polyhistor'?","o":["en særlig viden om historie alene","en stor viden på mange områder","en evne til at tale mange sprog","en lang række forskellige job"],"a":"en stor viden på mange områder","r":"Poly- betyder mange, og græsk 'histor' betyder lærd. Den, der taler mange sprog, er derimod polyglot."},
{"l":8890,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvordan lever en person, der lever 'asketisk'?","o":["meget luksuriøst og med mange tjenestefolk","helt alene på en ø uden forbindelse med land","meget enkelt og helt med vilje uden luksus","ofte på rejse og uden en fast bopæl"],"a":"meget enkelt og helt med vilje uden luksus","r":"Asketen afstår bevidst fra nydelse og overflod. Det kan ske af hensyn til et højere mål."},
{"l":8909,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'De sad over for hinanden i toget. Han læste avis, hun læste i en bog. Ingen af dem havde vendt en side, siden de kørte fra Odense.' Hvad kan læseren slutte?","o":["De har kun været i toget i ganske kort tid","De to er så optagede af læsningen, at de glemmer alt","De kan ikke se at læse, fordi lyset er for dårligt","De læser ikke, men er optaget af noget andet"],"a":"De læser ikke, men er optaget af noget andet","r":"Den, der ikke vender en side, læser ikke rigtigt. De sidder kun med avisen og bogen, og det tyder på, at de er optaget af noget andet, måske af hinanden."},
{"l":8927,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Emma har set tusind hvide svaner og slutter, at alle svaner er hvide. Hvilken slutningsform bruger hun?","o":["induktion","deduktion","reduktion","introduktion"],"a":"induktion","r":"Ved induktion slutter man fra enkelte tilfælde til en almen regel. Det er usikkert, for der findes faktisk sorte svaner."},
{"l":8948,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Hvis vi giver eleverne fri én fredag, vil de snart forlange hele ugen, og til sidst lukker skolen.' Hvilken argumentationsfejl er det?","o":["personangreb","glidebaneargument","cirkelslutning","falsk autoritet"],"a":"glidebaneargument","r":"Et lille skridt påstås at føre til noget ekstremt, uden at sammenhængen er vist. Det er et glidebaneargument."},
{"l":8970,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kaldes en betalt annonce, der er lavet til at ligne en almindelig artikel?","o":["klumme","leder","advertorial","notits"],"a":"advertorial","r":"Ordet er sat sammen af 'advertisement' og 'editorial'. Læseren skal være kritisk, fordi teksten er reklame i forklædning."},
{"l":8992,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken tænker i antikken beskrev appelformerne etos, patos og logos?","o":["Homer","Julius Cæsar","Pythagoras","Aristoteles"],"a":"Aristoteles","r":"Den græske filosof Aristoteles beskrev de tre appelformer i sit værk om retorik."},
{"l":9010,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Ordleddet 'iso-' står i 'isobar' og 'isoterm'. Hvad betyder det?","o":["lige eller ens","varm eller hed","rund eller buet","stor eller bred"],"a":"lige eller ens","r":"Græsk 'isos' betyder lige. En isobar er en linje på et vejrkort, der forbinder steder med samme lufttryk."},
{"l":9030,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Sæt ind: 'Ordene på, under og ved er hver en ___.'","o":["preposition","præposition","præpossition","præposision"],"a":"præposition","r":"Det latinske navn for forholdsord skrives med præ- og ét s og slutter på -tion."},
{"l":9048,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning om snevejret bruger semikolon rigtigt?","o":["Det sneede voldsomt derfor; blev skolen lukket.","Det sneede; voldsomt derfor blev skolen lukket.","Det sneede voldsomt; derfor blev skolen lukket.","Det; sneede voldsomt derfor blev skolen lukket."],"a":"Det sneede voldsomt; derfor blev skolen lukket.","r":"Semikolon står på grænsen mellem de to hovedsætninger, altså foran 'derfor'."},
{"l":9070,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"I hvilken sætning er 'at' et navneformsmærke?","o":["Nora siger, at boller er sunde.","Nora håber, at bollerne bliver gode.","Nora ved, at ovnen er varm.","Nora elsker at bage boller."],"a":"Nora elsker at bage boller.","r":"Navneformsmærket 'at' står foran et udsagnsord i navneform, her 'bage'. I de andre sætninger er 'at' et bindeord, der indleder en ledsætning."},
{"l":9091,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'O, du stille hav, hvor er du smuk i aftenlyset!' Hvad kaldes det, at digteren direkte tiltaler havet?","o":["apostrofe","kiasme","eufemisme","metonymi"],"a":"apostrofe","r":"Digteren taler direkte til havet, som om det kunne høre. Det kaldes apostrofe og er almindeligt i højstemt digtning."},
{"l":9112,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Overskrift i Bybladet: Borgmester afviser, at sagen om kantinen er en skandale.' Hvilken virkning kan overskriften have, selv om borgmesteren afviser?","o":["Læseren er nu sikker på, at der ikke er nogen sag","Læseren husker ordet skandale alligevel","Læseren får at vide, hvad sagen om kantinen går ud på","Læseren vil straks tro, at bladet er på hans side"],"a":"Læseren husker ordet skandale alligevel","r":"Et ord, der bliver afvist, står alligevel på tryk. Selve benægtelsen kan få ordet til at sætte sig fast."},
{"l":9126,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Forskerne målte passatvinden, monsunen og golfstrømmen fra et skib.'?","o":["passatvinden","monsunen","golfstrømmen","skib"],"a":"golfstrømmen","r":"Golfstrømmen er navnet på én bestemt havstrøm. Passatvind og monsun er betegnelser for slags vinde og skrives med lille."},
{"l":9152,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Efter hvilket ord skal der stå komma: 'Jo mere du øver jo bedre bliver du.'?","o":["mere","bedre","bliver","øver"],"a":"øver","r":"Første del med 'jo' er en ledsætning, og den slutter efter 'øver'."},
{"l":9171,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Foreningen skriver: Vi i lokalsamfundet ønsker ikke et nyt center. Foreningen har 40 medlemmer, og byen har 6.000 indbyggere.' Hvad gør foreningen med ordet 'vi'?","o":["Den lader 40 medlemmer tale på hele byens vegne","Den fortæller, hvor mange der er imod i procent","Den viser, at den ikke selv er med i debatten","Den skelner tydeligt mellem medlemmer og andre"],"a":"Den lader 40 medlemmer tale på hele byens vegne","r":"'Vi i lokalsamfundet' lyder som alle, men oplysningen bagefter afslører, hvor få der står bag. Et lille ord som 'vi' kan få nogle få til at lyde som mange."},
{"l":9191,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad er særligt ved vestjysk 'æ hus' sammenlignet med rigsdansk 'huset'?","o":["Navneordet står altid i flertal.","Kendeordet står foran navneordet.","Kendeordet står efter navneordet.","Navneordet står altid uden kendeord."],"a":"Kendeordet står foran navneordet.","r":"I vestjysk står det bestemte kendeord 'æ' foran navneordet. I rigsdansk sættes det bag på navneordet som en endelse: 'huset'."},
{"l":9212,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvor samlede Steen Steensen Blicher fra 1839 folk til store fester i det fri?","o":["Skamlingsbanken","Dybbøl Banke","Himmelbjerget","Mols Bjerge"],"a":"Himmelbjerget","r":"Blicher tog i 1839 initiativ til folkefesterne på Himmelbjerget. Her mødtes folk i naturen til taler og sang."},
{"l":9231,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Kritik af et forslag er ikke det samme som kritik af personen. Det burde være indlysende. Alligevel indledes de fleste svar i vores debat med ordene: Du har vist ikke forstået.' Hvad antyder skribenten om debatten?","o":["At de fleste debattører mangler viden om forslagene","At det er umuligt at kritisere forslag i et demokrati","At debatten bør foregå mundtligt i stedet for på skrift","At man ofte går efter personen frem for sagen"],"a":"At man ofte går efter personen frem for sagen","r":"'Du har vist ikke forstået' vender sig mod modparten, ikke forslaget. Eksemplet viser det, skribenten kritiserer."},
{"l":9254,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Sproget er i forfald, skrives der i avisernes læserbreve. Det samme blev skrevet for hundrede år siden, og længe før det. Hvis klagerne var rigtige, burde vi snart ikke kunne sige noget.' Hvad er skribentens argument?","o":["At klagerne er så gamle, at de ikke beviser noget om i dag","At aviser har skrevet mere om sprog før i tiden end i dag","At hundrede år gamle læserbreve er bedre skrevet end de nye","At sprogets forfald er blevet langt værre de seneste år"],"a":"At klagerne er så gamle, at de ikke beviser noget om i dag","r":"Skribenten bruger klagernes alder imod dem. Sidste sætning viser, at klagerne ikke kan passe: Så ville vi snart ikke kunne tale."},
{"l":9270,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'En sommerfugl har ___ omkring midten af kroppen.'","o":["symetri","symmetri","simmetri","symmetrie"],"a":"symmetri","r":"Ordet kommer fra græsk og skrives med y og dobbelt-m."},
{"l":9290,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Hele ugen havde han øvet sig på, hvad han ville sige. Han havde skrevet det ned og lært det udenad foran spejlet. Da hun åbnede døren, sagde han: Har du lånt min blyant?' Hvilken virkning har den sidste sætning?","o":["Den viser, at han kun ville have sin blyant igen","Den viser, at han er blevet modig af at øve sig","Den er sjov og lidt trist, for han får det ikke sagt","Den viser, at han er sur på hende over blyanten"],"a":"Den er sjov og lidt trist, for han får det ikke sagt","r":"Man venter, at han siger det, han har øvet sig på hele ugen. Men da hun står der, spørger han bare om en blyant. Det er både sjovt og lidt trist."},
{"l":9312,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"To naboer mødes: 'Hej, hvordan går det?' 'Jo tak, og dig?' Hvilken sprogfunktion er det?","o":["den metasproglige","den referentielle","den poetiske","den fatiske"],"a":"den fatiske","r":"Den fatiske funktion holder kontakten mellem mennesker i gang. Det vigtigste er ikke oplysningen, men at man hilser på hinanden."},
{"l":9334,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning har en fejl i brugen af spørgsmålstegn?","o":["Jeg undrer mig over, hvorfor du kom for sent?","Hvorfor kom du for sent?","Kom du for sent i dag?","Kom du for sent, fordi bussen var forsinket?"],"a":"Jeg undrer mig over, hvorfor du kom for sent?","r":"Det er et indirekte spørgsmål: Sætningen udtrykker en undren og skal slutte med punktum."},
{"l":9355,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad undersøger man i 'metafysik'?","o":["kroppens bevægelser under sport og leg","det, der ligger ud over det, vi kan se og måle","kræfter og bevægelser inde i de allermindste atomer","sprogets bøjninger og faste lydregler"],"a":"det, der ligger ud over det, vi kan se og måle","r":"Ordet kommer af græsk 'meta ta physika', det efter fysikken, om en del af Aristoteles' værker. I dag spørger metafysikken til det, der ligger bag den fysiske verden."},
{"l":9377,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad vil Adam Oehlenschläger sige med digtet 'Guldhornene'?","o":["Guld er det allervigtigste, et land kan eje og passe på","Hornene blev stjålet, fordi ingen passede på dem","Folk så kun guldet og forstod ikke, hvad hornene betød","Oldtidens mennesker kunne mere end folk i dag"],"a":"Folk så kun guldet og forstod ikke, hvad hornene betød","r":"I digtet giver guderne hornene som en gave fra fortiden. Men de forsvinder igen, fordi folk ser mere på guldet end på det hellige."},
{"l":9397,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Skolens værdigrundlag fylder 34 sider. Ingen elev kan nævne én af værdierne. Skolelederen vil nu lave en ny udgave med et bedre layout.' Hvad gør skribenten opmærksom på?","o":["At værdigrundlagets layout er det, der har skadet eleverne","At eleverne burde lære alle 34 sider udenad til prøven","At skolelederen bør skrive et langt kortere nyt værdigrundlag","At skolelederen løser et andet problem end det, der er"],"a":"At skolelederen løser et andet problem end det, der er","r":"Problemet er ikke udseendet, men at værdierne ikke lever blandt eleverne. Teksten siger det ikke, men sidste sætning gør det komisk."},
{"l":9420,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvilken stavemåde er rigtig? 'Haven havde en ___ af høje hække, som man kunne fare vild i.'","o":["labyrint","labbyrint","laburint","labyrinth"],"a":"labyrint","r":"Ordet kommer fra græsk og skrives med y, ét b og uden h til sidst."},
{"l":9443,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilket træk er typisk for barokkens digtning?","o":["Nøgterne beskrivelser af arbejderes kår","Stærke modsætninger og et pompøst sprog","Frie vers uden nogen rim eller rytme","Korte sætninger uden tillægsord"],"a":"Stærke modsætninger og et pompøst sprog","r":"Barokken dyrkede kontraster som liv og død og skrev i et overdådigt sprog."},
{"l":9464,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når en parentes står lige før et komma?","o":["Da Yusuf kom hjem, (ret sent) gik han i seng.","Da Yusuf kom hjem (ret sent, gik) han i seng.","Da Yusuf kom hjem (ret sent), gik han i seng.","Da Yusuf kom hjem (ret sent) gik, han i seng."],"a":"Da Yusuf kom hjem (ret sent), gik han i seng.","r":"Parentesen hører til ledsætningen, så kommaet står efter parentesen."},
{"l":9480,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'A: Bussen ramte cyklen. B: Cyklen blev ramt. C: Der skete et sammenstød.' Hvad sker der med sproget fra A til C?","o":["Det bliver mere og mere dramatisk","Der kommer flere og flere personer med","Det bliver tydeligere, hvornår det skete","Det bliver sværere at se, hvem der har skylden"],"a":"Det bliver sværere at se, hvem der har skylden","r":"I A er det bussen, der gør noget. I B er bussen væk, og i C står der slet ikke, hvem der gjorde hvad."},
{"l":9499,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Dansk 'gade' og 'bide' svarer til svensk 'gata' og 'bita'. Hvad viser det?","o":["Dansk svækkede t efter vokal.","Svensk ændrede d til t overalt.","Dansk lånte ordene fra tysk.","Svensk lånte ordene fra latin."],"a":"Dansk svækkede t efter vokal.","r":"I middelalderen blev p, t og k efter vokal svækket i dansk. Svensk bevarede dem, og derfor ser ordene så forskellige ud i dag."},
{"l":9521,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning har rigtig kongruens, når grundleddet indeholder 'et par'?","o":["Et par elever var sygt i fredags.","Et par elever var syge i fredags.","Et par elever var syg i fredags.","Et par elever er sygt i fredags."],"a":"Et par elever var syge i fredags.","r":"'Et par elever' betyder nogle få elever og tæller derfor som flertal. Tillægsordet skal have flertalsformen, selvom 'par' er intetkøn ental."},
{"l":9542,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning om slottet er tegnsat rigtigt?","o":["Kronborg, slottet i Helsingør er kendt fra »Hamlet«.","Kronborg slottet i Helsingør, er kendt fra »Hamlet«.","Kronborg, slottet i Helsingør, er kendt fra »Hamlet«.","Kronborg, slottet, i Helsingør er kendt fra »Hamlet«."],"a":"Kronborg, slottet i Helsingør, er kendt fra »Hamlet«.","r":"'slottet i Helsingør' er en apposition og skal have komma på begge sider."},
{"l":9565,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilke to pladser er tomme i sætningsskemaet for 'Luk døren!'?","o":["forfeltet og det bøjede udsagnsords plads","grundleddets plads og genstandsleddets plads","det bøjede udsagnsords plads og genstandsleddets plads","forfeltet og grundleddets plads"],"a":"forfeltet og grundleddets plads","r":"En bydesætning begynder med det bøjede udsagnsord og har ikke noget grundled. 'Døren' er genstandsled, så dén plads er fyldt."},
{"l":9586,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Jeg stod i køen hos bageren og tænkte på, hvad tid egentlig er. Er det noget, vi har, eller noget, der har os? Uret på væggen vidste det måske.' Hvilken genre passer bedst?","o":["essay","leder","notits","fabel"],"a":"essay","r":"Skribenten tager udgangspunkt i noget personligt og undrer sig åbent uden at konkludere. Det er essayets kendetegn."},
{"l":9602,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"I en retssag siger advokaten, at køberen handlede 'bona fide'. Hvad betyder det?","o":["med onde hensigter","i god tro","med advokatens hjælp","uden at betale"],"a":"i god tro","r":"Latin 'bona fide' betyder i god tro. Køberen vidste altså ikke, at der var noget galt med handlen."},
{"l":9625,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad gør man, når man fører et argument 'ad absurdum'?","o":["gentager det, til alle er enige","omskriver det med finere og mere højtidelige ord","viser, at det fører til noget urimeligt","lader en anden føre det videre"],"a":"viser, at det fører til noget urimeligt","r":"Man trækker påstanden til sin yderste konsekvens for at afsløre, at den ikke holder."},
{"l":9646,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvor mange kommaer kræver reglerne i 'Selvom Ida havde travlt hjalp hun Noah og Asta trøstede Emil.'?","o":["ét komma","tre kommaer","fire kommaer","to kommaer"],"a":"to kommaer","r":"Der skal komma efter ledsætningen, der slutter med 'travlt', og foran 'og', fordi 'Asta' er et nyt grundled."},
{"l":9670,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'sinekure'?","o":["en velbetalt stilling med meget lidt arbejde","en langvarig behandling på et kursted","en dårligt lønnet stilling med mange pligter","en midlertidig stilling i en anden by"],"a":"en velbetalt stilling med meget lidt arbejde","r":"Latin 'sine cura' betyder uden bekymring. Ordet bruges ofte kritisk om en behagelig post."},
{"l":9686,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad tilføjer forleddet 'ærke-' i 'ærkefjende'?","o":["kun i ringe grad","i særlig høj grad","ikke længere","en gang til"],"a":"i særlig høj grad","r":"'Ærke-' forstærker ordet. En ærkefjende er den værste fjende, man kan have."},
{"l":9707,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Da hegnet omkring legepladsen blev fjernet, ændrede børnene adfærd, fortæller pædagogen. Før løb de helt ud til kanten. Nu holder de sig tæt på midten.' Hvad kan iagttagelsen bruges som billede på?","o":["At børn altid foretrækker at lege helt uden hegn","At hegn gør børn mere bange end ingen hegn","At klare grænser kan give en følelse af frihed","At børn løber mest, når der ikke er hegn"],"a":"At klare grænser kan give en følelse af frihed","r":"Med hegn turde børnene bruge hele arealet, uden hegn kun en lille del. Hegnet gav dem tryghed, så de turde mere."},
{"l":9730,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kendetegner en 'vederhæftig' kilde?","o":["gammel og ukendt","skjult og hemmelig","mundtlig og uformel","pålidelig og troværdig"],"a":"pålidelig og troværdig","r":"Vederhæftig betyder, at man kan hæfte for det, der siges. Ordet bruges også om en person, der kan betale sin gæld."},
{"l":9750,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvorfor er der ikke komma foran 'og' i 'Hvis du kommer og hjælper, bliver vi færdige.'?","o":["Fordi 'og' binder to udsagn i samme ledsætning","Fordi 'hjælper' er sidste ord i hovedsætningen","Fordi 'og' aldrig må have komma foran sig","Fordi 'du' er genstandsled i ledsætningen"],"a":"Fordi 'og' binder to udsagn i samme ledsætning","r":"'kommer' og 'hjælper' deler grundleddet 'du', så der er kun én ledsætning med to udsagnsled."},
{"l":9773,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad er en grundoplevelse i modernismen?","o":["Tryghed i en verden med faste værdier","Fremmedgørelse i en verden uden faste værdier","Glæde over naturens guddommelige helhed","Tillid til, at samfundet bliver stadig bedre"],"a":"Fremmedgørelse i en verden uden faste værdier","r":"Modernisterne oplevede, at de gamle sandheder var brudt sammen. Mennesket står alene og fremmed i en splittet verden."},
{"l":9790,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Læs: 'Min faster har en idiosynkrasi mod høje lyde.' Hvad har hun?","o":["en stor og varig kærlighed til dem","en dyb faglig viden","en stærk og personlig modvilje","en vane fra barndommen"],"a":"en stærk og personlig modvilje","r":"Idiosynkrasi kommer af græsk for 'egen blanding'. Det er en stærk, ofte ufornuftig modvilje mod noget bestemt."},
{"l":9810,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find ordet: 'Opgaven sluttede med en ___ over, hvad hun havde lært.'","o":["refleksjon","refleksiun","reflektion","refleksion"],"a":"refleksion","r":"Ordet skrives med ks og -ion. Mange skriver -ktion, men det er forkert her."},
{"l":9829,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Den første hele bibel på dansk, Christian 3.s Bibel, fik stor betydning for skriftsproget. Hvornår udkom den?","o":["i 1550","i 1241","i 1849","i 1948"],"a":"i 1550","r":"Bibelen fra 1550 kom efter reformationen i 1536 og blev læst i hele landet. Dens sprog blev et forbillede for dansk skriftsprog."},
{"l":9851,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"En læge skriver: 'Patienten har en fraktur på radius.' Hvad kendetegner sproget her?","o":["slang, som kun unge bruger","præcise fagudtryk for fagfolk","ord fra en bestemt landsdel","gammeldags ord fra kancelliet"],"a":"præcise fagudtryk for fagfolk","r":"Fagsprog bruger præcise ord, der er lette at forstå for fagfolk. 'Fraktur' betyder brud, og 'radius' er en knogle i underarmen."},
{"l":9873,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Vi siger, at vi stoler på forskning. Men når to forskere er uenige, kalder vi det et tegn på, at ingen ved noget. I virkeligheden er uenighed det sted, hvor forskningen foregår.' Hvilken misforståelse vil skribenten rette?","o":["At forskere altid er enige, når de ikke taler med pressen","At alle forskere har lige ret i alle spørgsmål hver gang","At uenige forskere viser, at ingen ved noget","At offentligheden stoler for lidt på forskeres resultater"],"a":"At uenige forskere viser, at ingen ved noget","r":"Skribenten siger, at uenighed er en normal del af forskning. Pointen er ikke, at alle har ret."},
{"l":9895,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Når forskerne i et helt fag begynder at tænke helt nyt, taler man om et paradigmeskift. Hvad er et 'paradigme'?","o":["et enkelt forsøg, der er mislykkedes","en ny måleenhed for videnskabelige data","en person, der leder et forskningsfag","den fælles måde at tænke på i et fag"],"a":"den fælles måde at tænke på i et fag","r":"Thomas Kuhn gjorde ordet kendt. Et paradigme er den ramme, som forskerne i en periode tænker og arbejder inden for."},
{"l":9916,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Jeg er uddannet børnelæge og har arbejdet med søvn i tyve år. Tallene fra kommunen viser, at hvert tredje barn sover for lidt.' Hvilke appelformer bruges, og i hvilken rækkefølge?","o":["Først etos, så logos","Først patos, så etos","Først logos, så patos","Først logos, så etos"],"a":"Først etos, så logos","r":"Afsenderen viser først sin faglige troværdighed. Derefter kommer et tal, som taler til fornuften."},
{"l":9933,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Når modstanderne scorer på en bold, der rammer stolpen først, siger vores fans, at det var held. Når vi selv scorer på samme måde, siger de, at det var godt set af angriberen. Det er det samme mål med to forskellige navne. Bolden ved ikke, hvem den spiller for.' Hvad betyder den sidste sætning?","o":["En bold kan ikke styres, når den rammer stolpen.","Målet er lige heldigt, uanset hvem der scorer.","Fansene ved ikke, hvilket hold der har scoret.","Angriberen ved ikke, hvor bolden ender henne."],"a":"Målet er lige heldigt, uanset hvem der scorer.","r":"En bold er bare en bold, så den er ikke heldig for det ene hold og dygtig for det andet. Det er kun fansene, der kalder det samme mål noget forskelligt."},
{"l":9958,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning indeholder ingen fejl i tegn og tal?","o":["Jens's mor købte to cd'er kl. 16.30 i Aalborg.","Jens' mor købte to cd'er kl. 16,30 i Aalborg.","Jens' mor købte to cd'er kl. 16.30 i Aalborg.","Jens' mor købte to c.d.er kl. 16.30 i Aalborg."],"a":"Jens' mor købte to cd'er kl. 16.30 i Aalborg.","r":"Genitiv af Jens får kun apostrof, cd bøjes med apostrof, og klokkeslæt skrives med punktum."},
{"l":9977,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En økonom skriver: 'Ceteris paribus vil højere priser give lavere salg.' Hvad betyder det latinske udtryk?","o":["uden undtagelse","på langt sigt","ifølge loven","alt andet lige"],"a":"alt andet lige","r":"Økonomer bruger udtrykket, når de holder alle andre forhold fast og kun ser på sammenhængen mellem to ting."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
